import { useState } from "react";
import axios from "axios";

export default function Cadastro() {
  const [formData, setFormData] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    foto: null,
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    setFormData({ ...formData, foto: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    data.append("nome", formData.nome);
    data.append("idade", formData.idade);
    data.append("rua", formData.rua);
    data.append("bairro", formData.bairro);
    data.append("estado", formData.estado);
    data.append("biografia", formData.biografia);
    data.append("foto", formData.foto); // nome do campo deve ser "foto"

    try {
      await axios.post("http://localhost:3001/usuarios", data);
      alert("Usuário cadastrado com sucesso!");
    } catch (error) {
      console.error("Erro ao cadastrar:", error);
      alert("Erro ao cadastrar usuário.");
    }
  };

  return (
    <div>
      <h2>Cadastrar Novo Usuário</h2>
      <form onSubmit={handleSubmit} encType="multipart/form-data">
        <input
          name="nome"
          placeholder="Nome completo"
          value={formData.nome}
          onChange={handleChange}
          required
        />
        <br />
        <input
          name="idade"
          placeholder="Idade"
          type="number"
          value={formData.idade}
          onChange={handleChange}
          required
        />
        <br />
        <input
          name="rua"
          placeholder="Rua"
          value={formData.rua}
          onChange={handleChange}
          required
        />
        <br />
        <input
          name="bairro"
          placeholder="Bairro"
          value={formData.bairro}
          onChange={handleChange}
          required
        />
        <br />
        <input
          name="estado"
          placeholder="Estado"
          value={formData.estado}
          onChange={handleChange}
          required
        />
        <br />
        <textarea
          name="biografia"
          placeholder="Biografia"
          value={formData.biografia}
          onChange={handleChange}
        />
        <br />
        <input type="file" name="foto" accept="image/*" onChange={handleFileChange} required />
        <br />
        <button type="submit">Cadastrar</button>
      </form>
    </div>
  );
}
